import { apiBaseUrl } from './apiClient';

type SignupRequestParams = {
  name: string;
  email: string;
  mobileNumber: string;
};

type ApiErrorCode =
  | 'INVALID_INPUT'
  | 'OTP_NOT_FOUND'
  | 'OTP_EXPIRED'
  | 'OTP_INVALID'
  | 'OTP_DELIVERY_FAILED'
  | 'OTP_RATE_LIMITED'
  | 'OTP_RESEND_NOT_READY'
  | 'OTP_TOO_MANY_ATTEMPTS'
  | 'AUTH_CONTACT_CONFLICT'
  | 'PIN_USER_NOT_FOUND'
  | 'PIN_INVALID'
  | 'PIN_LOCKED'
  | 'PIN_REUSE_NOT_ALLOWED'
  | 'PIN_ALREADY_CONFIGURED'
  | 'NETWORK_OFFLINE'
  | 'SERVER_ERROR';

export type AuthSessionResponse = {
  sessionToken: string;
  requiresPinChange?: boolean;
  requiresPinSetup?: boolean;
  user: {
    id: string;
    name: string;
    email: string;
    mobileNumber: string;
    createdAtISO?: string;
  };
  client?: {
    fiteatsyClientId: string;
    status: string;
  };
};

export type CurrentAuthSession = {
  accountId: string;
  sessionId: string;
  sessionExpiresAtISO: string;
  requiresPinSetup: boolean;
  requiresPinChange: boolean;
  client: {
    fiteatsyClientId: string;
    status: string;
  };
  user: {
    id: string;
    name: string;
    email: string;
    mobileNumber: string;
    createdAtISO?: string;
  };
};

export class AuthServiceError extends Error {
  code: ApiErrorCode;
  retryAfterSec?: number;

  constructor(code: ApiErrorCode, message: string, retryAfterSec?: number) {
    super(message);
    this.code = code;
    this.retryAfterSec = retryAfterSec;
  }
}

const AUTH_LOG_PREFIX = '[AuthService]';
const REDACTED = '[REDACTED]';
const authLogger = {
  log: (...values: unknown[]) => { if (__DEV__) console.log(...values); },
  warn: (...values: unknown[]) => { if (__DEV__) console.warn(...values); },
  error: (...values: unknown[]) => { if (__DEV__) console.error(...values); }
};

const sanitizeAuthPayload = (value: unknown): unknown => {
  if (Array.isArray(value)) {
    return value.map(sanitizeAuthPayload);
  }

  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([key, entry]) => {
        const normalizedKey = key.toLowerCase();
        if (
          normalizedKey.includes('authorization') ||
          normalizedKey.includes('token') ||
          normalizedKey === 'otp' ||
          normalizedKey.includes('phonenumber') ||
          normalizedKey.includes('mobile')
        ) {
          return [key, REDACTED];
        }
        return [key, sanitizeAuthPayload(entry)];
      })
    );
  }

  return value;
};

const formatValidationDetails = (details: unknown) => {
  if (!details || typeof details !== 'object') return null;
  const fieldErrors = (details as { fieldErrors?: Record<string, unknown> }).fieldErrors;
  if (!fieldErrors || typeof fieldErrors !== 'object') return null;

  const labels: Record<string, string> = {
    name: 'Name',
    email: 'Email',
    mobile: 'Mobile number',
    mobileNumber: 'Mobile number',
    pin: 'PIN',
    otp: 'OTP',
    challengeId: 'OTP request'
  };

  const messages = Object.entries(fieldErrors)
    .flatMap(([field, errors]) => {
      if (!Array.isArray(errors)) return [];
      return errors.map((message) => `${labels[field] ?? field}: ${String(message)}`);
    })
    .filter(Boolean);

  return messages.length > 0 ? messages.join('\n') : null;
};

const parseError = async (response: Response, url: string): Promise<never> => {
  let payload: { error?: ApiErrorCode; message?: string; retryAfterSec?: number; details?: unknown } = {};
  let responseText = '';
  try {
    responseText = await response.text();
    payload = responseText ? (JSON.parse(responseText) as typeof payload) : {};
    authLogger.warn(`${AUTH_LOG_PREFIX} ERROR RESPONSE`, {
      url,
      status: response.status,
      responseJson: sanitizeAuthPayload(payload)
    });
  } catch (error) {
    authLogger.error(`${AUTH_LOG_PREFIX} ERROR RESPONSE PARSE FAILED`, {
      url,
      status: response.status,
      responseText,
      errorMessage: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined
    });
    payload = {};
  }
  const validationMessage = payload.error === 'INVALID_INPUT' ? formatValidationDetails(payload.details) : null;
  throw new AuthServiceError(
    payload.error ?? 'SERVER_ERROR',
    validationMessage ?? payload.message ?? 'Unable to complete authentication request.',
    payload.retryAfterSec
  );
};

const requestJson = async <T>(
  path: string,
  init: RequestInit & { skipJsonBody?: boolean } = {}
): Promise<T> => {
  let response: Response;
  const url = `${apiBaseUrl}${path}`;
  const method = init.method ?? 'GET';
  authLogger.log(`${AUTH_LOG_PREFIX} REQUEST`, { apiBaseUrl, url, method });
  try {
    response = await fetch(url, {
      ...init,
      headers: {
        ...(init.skipJsonBody ? {} : { 'Content-Type': 'application/json' }),
        ...(init.headers ?? {})
      }
    });
  } catch (error) {
    authLogger.error(`${AUTH_LOG_PREFIX} FETCH FAILED`, {
      apiBaseUrl,
      url,
      method,
      errorMessage: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined
    });
    throw new AuthServiceError('NETWORK_OFFLINE', `Unable to reach the authentication service at ${apiBaseUrl}.`);
  }

  authLogger.log(`${AUTH_LOG_PREFIX} RESPONSE STATUS`, { url, status: response.status });

  if (!response.ok) {
    return parseError(response, url);
  }

  if (response.status === 204) {
    authLogger.log(`${AUTH_LOG_PREFIX} RESPONSE EMPTY`, { url, status: response.status });
    return undefined as T;
  }

  let responseText = '';
  try {
    responseText = await response.text();
    const payload = (responseText ? JSON.parse(responseText) : undefined) as T;
    authLogger.log(`${AUTH_LOG_PREFIX} RESPONSE JSON`, {
      url,
      status: response.status,
      responseJson: sanitizeAuthPayload(payload)
    });
    return payload;
  } catch (error) {
    authLogger.error(`${AUTH_LOG_PREFIX} RESPONSE PARSE FAILED`, {
      url,
      status: response.status,
      responseText,
      errorMessage: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined
    });
    throw new AuthServiceError('SERVER_ERROR', 'Authentication service returned an unreadable response.');
  }
};

export type SignupOtpResponse = {
  challengeId: string;
  expiresAtISO: string;
  resendAvailableAtISO: string;
  attemptsRemaining: number;
  deliveryChannel: {
    emailMasked: string;
    mobileMasked: string;
  };
};

export const requestSignupOtp = (params: SignupRequestParams) =>
  requestJson<SignupOtpResponse>('/v1/auth/signup/request-otp', {
    method: 'POST',
    body: JSON.stringify(params)
  });

export const loginWithPin = (params: { mobile: string; pin: string }) =>
  requestJson<AuthSessionResponse>('/v1/auth/login/pin', {
    method: 'POST',
    body: JSON.stringify(params)
  });

export const changePin = (sessionToken: string, params: { currentPin: string; newPin: string; confirmNewPin: string }) =>
  requestJson<{ ok: true }>('/v1/auth/change-pin', {
    method: 'PUT',
    headers: {
      Authorization: `Bearer ${sessionToken}`
    },
    body: JSON.stringify(params)
  });

export const createLoginPin = (sessionToken: string, params: { newPin: string; confirmNewPin: string }) =>
  requestJson<{ ok: true }>('/v1/auth/create-pin', {
    method: 'PUT',
    headers: { Authorization: `Bearer ${sessionToken}` },
    body: JSON.stringify(params)
  });

export const resendSignupOtp = (challengeId: string) =>
  requestJson<SignupOtpResponse>('/v1/auth/signup/resend-otp', {
    method: 'POST',
    body: JSON.stringify({ challengeId })
  });

export const verifySignupOtp = (challengeId: string, otp: string) =>
  requestJson<AuthSessionResponse>('/v1/auth/signup/verify-otp', {
    method: 'POST',
    body: JSON.stringify({ challengeId, otp })
  });

export const getCurrentAuthSession = (sessionToken: string) =>
  requestJson<CurrentAuthSession>('/v1/auth/me', {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${sessionToken}`
    },
    skipJsonBody: true
  });

export const buildSessionFromAuthResponse = (session: AuthSessionResponse): CurrentAuthSession | null => {
  if (!session.client?.fiteatsyClientId) return null;
  return {
    accountId: session.user.id,
    sessionId: `fresh-login:${session.user.id}`,
    sessionExpiresAtISO: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
    requiresPinSetup: session.requiresPinSetup === true,
    requiresPinChange: session.requiresPinChange === true,
    client: {
      fiteatsyClientId: session.client.fiteatsyClientId,
      status: session.client.status
    },
    user: {
      id: session.user.id,
      name: session.user.name,
      email: session.user.email,
      mobileNumber: session.user.mobileNumber,
      createdAtISO: session.user.createdAtISO
    }
  };
};

export const logoutAuthSession = (sessionToken: string) =>
  requestJson<void>('/v1/auth/logout', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${sessionToken}`
    },
    body: JSON.stringify({})
  });
