import React, { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';
import Ionicons from '@expo/vector-icons/Ionicons';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { Screen } from '../../components/Screen';
import { AppBackButton } from '../../components/AppBackButton';
import { getThemeColors } from '../../design/tokens';
import { RootStackParamList } from '../../navigation/types';
import { ApiClientError } from '../../services/apiClient';
import { formatPlanPrice, getMySubscription, getPaymentHistory, FoundationSubscription, PaymentHistoryItem } from '../../services/subscriptionService';
import { useAppContext } from '../../state/AppContext';

type Props = NativeStackScreenProps<RootStackParamList, 'MySubscription'>;
const dateLabel = (iso: string | null | undefined) => iso ? new Date(iso).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : 'Not available';

export const MySubscriptionScreen = ({ navigation }: Props) => {
  const { themeMode } = useAppContext();
  const palette = getThemeColors(themeMode);
  const [data, setData] = useState<FoundationSubscription | null>(null);
  const [payments, setPayments] = useState<PaymentHistoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const next = await getMySubscription();
      setData(next);
      setPayments((await getPaymentHistory().catch(() => ({ payments: [] }))).payments);
    } catch (cause) {
      setError(cause instanceof ApiClientError ? cause.message : 'Unable to load your subscription right now.');
    } finally { setLoading(false); }
  }, []);
  useEffect(() => { void load(); }, [load]);
  const subscription = data?.subscription;
  return <Screen scroll contentStyle={styles.screen}>
    <AppBackButton onPress={() => navigation.goBack()} label="Profile" />
    <Text style={[styles.title, { color: palette.textPrimary }]}>My Subscription</Text>
    {loading ? <View style={styles.state}><ActivityIndicator color="#64D900" /><Text style={[styles.body, { color: palette.textSecondary }]}>Loading subscription…</Text></View> : null}
    {!loading && error ? <View style={styles.state}><Text accessibilityRole="alert" style={styles.error}>{error}</Text><Pressable accessibilityRole="button" onPress={() => { void load(); }} style={styles.primary}><Text style={styles.primaryText}>Retry</Text></Pressable></View> : null}
    {!loading && !error && data?.status === 'NONE' ? <View style={styles.empty}><Ionicons name="leaf-outline" size={30} color="#B59CFF" /><Text style={[styles.section, { color: palette.textPrimary }]}>No active plan</Text><Text style={[styles.body, { color: palette.textSecondary }]}>Choose a wellness plan to understand what is included and its validity.</Text><Pressable accessibilityRole="button" onPress={() => navigation.navigate('SubscriptionPlans')} style={styles.primary}><Text style={styles.primaryText}>Explore plans</Text></Pressable></View> : null}
    {!loading && !error && data && data.status !== 'NONE' ? <>
      <View style={[styles.card, { borderColor: data.status === 'EXPIRING_SOON' ? '#9C7435' : palette.stroke }]}><Text style={styles.eyebrow}>{data.status.replace(/_/g, ' ')}</Text><Text style={[styles.plan, { color: palette.textPrimary }]}>{subscription?.planName ?? 'Fiteatsy plan'}</Text><Text style={[styles.body, { color: palette.textSecondary }]}>Valid until {dateLabel(subscription?.expiresAt)}</Text>{subscription?.daysRemaining ? <Text style={styles.remaining}>{subscription.daysRemaining} days remaining</Text> : null}<Text style={[styles.body, { color: palette.textSecondary }]}>Plan value {formatPlanPrice({ priceMinor: subscription?.amountMinor ?? 0, currency: subscription?.currency ?? 'INR' })}</Text></View>
      <Text style={[styles.section, { color: palette.textPrimary }]}>Included with your plan</Text>
      {Object.entries(data.entitlements).map(([key, item]) => <View key={key} style={styles.row}><Ionicons name="checkmark-circle-outline" size={18} color="#B59CFF" /><Text style={[styles.body, { color: palette.textSecondary }]}>{key.replace(/_/g, ' ')}{item.value != null && item.value !== true ? ` · ${item.value}` : ''}</Text></View>)}
      {subscription?.planId ? <Pressable accessibilityRole="button" onPress={() => navigation.navigate('SubscriptionPlanDetails', { planId: subscription.planId })} style={styles.secondary}><Text style={styles.secondaryText}>View plan</Text></Pressable> : null}
      {data.status === 'EXPIRED' || data.status === 'EXPIRING_SOON' ? <Pressable accessibilityRole="button" onPress={() => navigation.navigate('SubscriptionPlans')} style={styles.primary}><Text style={styles.primaryText}>{data.status === 'EXPIRED' ? 'View plans' : 'Renew plan'}</Text></Pressable> : null}
      {payments.length > 0 ? <><Text style={[styles.section, { color: palette.textPrimary }]}>Payment history</Text>{payments.map((payment) => <View key={payment.id} style={styles.paymentRow}><Text style={[styles.body, { color: palette.textPrimary }]}>{payment.planName ?? 'Fiteatsy plan'}</Text><Text style={[styles.paymentMeta, { color: palette.textSecondary }]}>{payment.status} · {formatPlanPrice(payment)} · {new Date(payment.createdAt).toLocaleDateString()}</Text></View>)}</> : null}
    </> : null}
  </Screen>;
};

const styles = StyleSheet.create({
  screen: { gap: 16 }, title: { fontFamily: 'Exo_700Bold', fontSize: 28 }, state: { alignItems: 'center', gap: 14, paddingVertical: 28 }, empty: { alignItems: 'center', gap: 12, paddingVertical: 24 }, card: { borderWidth: 1, borderRadius: 18, padding: 18, gap: 8 }, eyebrow: { color: '#B59CFF', fontFamily: 'Exo_700Bold', fontSize: 11, letterSpacing: 1 }, plan: { fontFamily: 'Exo_700Bold', fontSize: 22 }, section: { fontFamily: 'Exo_700Bold', fontSize: 18 }, body: { fontFamily: 'Exo_400Regular', fontSize: 14, lineHeight: 20 }, remaining: { color: '#C8A15B', fontFamily: 'Exo_600SemiBold', fontSize: 14 }, row: { flexDirection: 'row', alignItems: 'center', gap: 9 }, paymentRow: { gap: 4, paddingVertical: 8, borderBottomWidth: 1, borderBottomColor: '#2A2635' }, paymentMeta: { fontFamily: 'Exo_400Regular', fontSize: 12 }, error: { color: '#F5A3AE', fontFamily: 'Exo_500Medium', fontSize: 14, textAlign: 'center' }, primary: { minHeight: 48, borderRadius: 12, backgroundColor: '#6A4FB3', alignItems: 'center', justifyContent: 'center', paddingHorizontal: 16 }, primaryText: { color: '#FFFFFF', fontFamily: 'Exo_700Bold', fontSize: 15 }, secondary: { minHeight: 46, borderRadius: 12, borderWidth: 1, borderColor: '#6A4FB3', alignItems: 'center', justifyContent: 'center' }, secondaryText: { color: '#C9B8FF', fontFamily: 'Exo_700Bold', fontSize: 14 }
});
