import React, { useEffect, useMemo, useRef, useState } from 'react';
import { ActivityIndicator, KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import Ionicons from '@expo/vector-icons/Ionicons';
import { Card } from '../../components/Card';
import { AppBackButton } from '../../components/AppBackButton';
import { getThemeColors, typography } from '../../design/tokens';
import { RootStackParamList } from '../../navigation/types';
import { useAppContext } from '../../state/AppContext';
import { connectExternalConsultant, ConnectionPreview, ConsultantScope, previewExternalConsultant } from '../../services/externalConsultantService';

type Props = NativeStackScreenProps<RootStackParamList, 'ConnectConsultant'>;
const scopeCopy: Record<ConsultantScope, { title: string; detail: string }> = {
  PROFILE: { title: 'Profile', detail: 'Your name and care profile.' }, HEALTH_SUMMARY: { title: 'Health summary', detail: 'Wellness summaries and trends.' }, MEASUREMENTS: { title: 'Measurements', detail: 'Consented body and activity measurements.' }, BIOMARKERS: { title: 'Biomarkers', detail: 'Consented report-derived biomarker results.' }, DIET_PLANS: { title: 'Diet plans', detail: 'Plans your consultant publishes to you.' }, APPOINTMENTS: { title: 'Appointments', detail: 'Appointments shared with this consultant.' }
};
const makeKey = () => `00000000-0000-4000-8000-${Date.now().toString(16).padStart(12, '0').slice(-12)}`;

export const ConnectConsultantScreen = ({ navigation }: Props) => {
  const { authSession, themeMode } = useAppContext(); const palette = getThemeColors(themeMode);
  const [pin, setPin] = useState(''); const [preview, setPreview] = useState<ConnectionPreview | null>(null); const [accepted, setAccepted] = useState<ConsultantScope[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const replayKey = useRef(makeKey());
  useEffect(() => () => { setPin(''); setPreview(null); setAccepted([]); }, []);
  const normalized = useMemo(() => pin.replace(/\D/g, '').slice(0, 6), [pin]);
  const sessionToken = authSession?.sessionToken ?? '';
  const review = async () => { setBusy(true); setError(null); try { const result = await previewExternalConsultant(normalized, sessionToken); setPreview(result); setAccepted(result.requested_scopes); } catch (reason) { setError(reason instanceof Error ? reason.message : 'PIN verification failed.'); } finally { setBusy(false); } };
  const connect = async () => { if (!preview || accepted.length === 0) return; setBusy(true); setError(null); try { const result = await connectExternalConsultant(normalized, accepted, sessionToken, replayKey.current); setPin(''); setPreview(null); navigation.replace('ConsultantConnectionDetails', { connectionId: result.connection_id }); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Connection failed.'); } finally { setBusy(false); } };
  const toggle = (scope: ConsultantScope) => setAccepted((current) => current.includes(scope) ? current.filter((item) => item !== scope) : [...current, scope]);
  const consultantName = preview?.consultant?.display_name || 'Consultant profile unavailable';

  return <KeyboardAvoidingView style={[styles.fill, { backgroundColor: palette.bgPrimary }]} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
    <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
      <View style={styles.header}><AppBackButton onPress={() => navigation.goBack()} /><Text style={[styles.title, { color: palette.textPrimary }]}>Connect Consultant</Text><View style={styles.placeholder} /></View>
      {!sessionToken ? <Card style={styles.profileCard}><View style={styles.profileMeta}><Text style={[styles.cardTitle, { color: palette.textPrimary }]}>Sign in required</Text><Text style={[styles.body, { color: palette.textSecondary }]}>Consultant Connection PINs can only be reviewed from an authenticated Fiteatsy account.</Text><Pressable style={[styles.primary, { backgroundColor: palette.blue }]} onPress={() => navigation.navigate('SignIn')}><Text style={styles.primaryText}>Sign in to continue</Text></Pressable></View></Card> : null}
      {sessionToken ? <>
      {!preview ? <><Text style={[styles.hero, { color: palette.textPrimary }]}>Enter your Connection PIN</Text><Text style={[styles.body, { color: palette.textSecondary }]}>Your consultant creates this single-use PIN in Zestiva 360. It expires automatically and is never saved on this device.</Text><TextInput accessibilityLabel="Connection PIN" keyboardType="number-pad" textContentType="oneTimeCode" autoComplete="one-time-code" autoCorrect={false} value={pin} onChangeText={setPin} maxLength={6} placeholder="6-digit PIN" placeholderTextColor={palette.textSecondary} style={[styles.input, { color: palette.textPrimary, borderColor: error ? '#FF5A5F' : palette.stroke, backgroundColor: palette.card }]} />{error ? <Text accessibilityRole="alert" style={styles.error}>{error}</Text> : null}<Pressable disabled={busy || normalized.length !== 6} style={[styles.primary, { backgroundColor: palette.blue }, (busy || normalized.length !== 6) && styles.disabled]} onPress={() => void review()}>{busy ? <ActivityIndicator color="#FFFFFF" /> : <Text style={styles.primaryText}>Review Consultant</Text>}</Pressable></> : <>
        <Card style={styles.profileCard}><View style={[styles.avatar, { backgroundColor: palette.cardMuted }]}><Text style={[styles.avatarText, { color: palette.blue }]}>{consultantName.slice(0, 1).toUpperCase()}</Text></View><View style={styles.profileMeta}><Text style={[styles.cardTitle, { color: palette.textPrimary }]}>{consultantName}</Text><Text style={[styles.body, { color: palette.textSecondary }]}>{preview.consultant?.headline || preview.consultant?.specialisations?.join(' · ') || 'Confirm identity with your consultant before continuing.'}</Text>{preview.consultant?.verified_qualifications ? <Text style={styles.verified}>✓ {preview.consultant.verified_qualifications} verified qualification{preview.consultant.verified_qualifications === 1 ? '' : 's'}</Text> : null}</View></Card>
        <Text style={[styles.sectionTitle, { color: palette.textPrimary }]}>Choose what to share</Text><Text style={[styles.body, { color: palette.textSecondary }]}>Access applies only to this consultant. You can disconnect at any time.</Text>
        <Card style={styles.scopeCard}>{preview.requested_scopes.map((scope, index) => <Pressable key={scope} accessibilityRole="checkbox" accessibilityState={{ checked: accepted.includes(scope) }} style={[styles.scopeRow, index > 0 && { borderTopColor: palette.stroke, borderTopWidth: StyleSheet.hairlineWidth }]} onPress={() => toggle(scope)}><Ionicons name={accepted.includes(scope) ? 'checkmark-circle' : 'ellipse-outline'} size={24} color={accepted.includes(scope) ? palette.blue : palette.textSecondary} /><View style={styles.scopeMeta}><Text style={[styles.scopeTitle, { color: palette.textPrimary }]}>{scopeCopy[scope].title}</Text><Text style={[styles.scopeDetail, { color: palette.textSecondary }]}>{scopeCopy[scope].detail}</Text></View></Pressable>)}</Card>
        {error ? <Text accessibilityRole="alert" style={styles.error}>{error}</Text> : null}<Pressable disabled={busy || accepted.length === 0} style={[styles.primary, { backgroundColor: palette.blue }, (busy || accepted.length === 0) && styles.disabled]} onPress={() => void connect()}>{busy ? <ActivityIndicator color="#FFFFFF" /> : <Text style={styles.primaryText}>Allow and Connect</Text>}</Pressable><Pressable disabled={busy} onPress={() => { setPreview(null); setAccepted([]); setError(null); replayKey.current = makeKey(); }}><Text style={[styles.secondary, { color: palette.blue }]}>Use a different PIN</Text></Pressable>
      </>}
      </> : null}
    </ScrollView>
  </KeyboardAvoidingView>;
};

const styles = StyleSheet.create({ fill: { flex: 1 }, content: { paddingHorizontal: 20, paddingTop: 14, paddingBottom: 48, gap: 16 }, header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }, circle: { width: 44, height: 44, borderWidth: 1, borderRadius: 22, alignItems: 'center', justifyContent: 'center' }, placeholder: { width: 44 }, title: { ...typography.h3 }, hero: { ...typography.h1, marginTop: 20 }, body: { ...typography.body, lineHeight: 22 }, input: { minHeight: 58, borderWidth: 1, borderRadius: 16, paddingHorizontal: 18, fontSize: 20, letterSpacing: 2, fontWeight: '700' }, error: { color: '#FF6B6B', fontSize: 14, lineHeight: 20 }, primary: { minHeight: 54, borderRadius: 17, alignItems: 'center', justifyContent: 'center' }, disabled: { opacity: 0.45 }, primaryText: { color: '#FFFFFF', fontSize: 17, fontWeight: '700' }, profileCard: { padding: 18, flexDirection: 'row', gap: 14 }, avatar: { width: 54, height: 54, borderRadius: 18, alignItems: 'center', justifyContent: 'center' }, avatarText: { fontSize: 23, fontWeight: '700' }, profileMeta: { flex: 1, gap: 5 }, cardTitle: { ...typography.h3 }, verified: { color: '#59D12B', fontSize: 13, fontWeight: '700' }, sectionTitle: { ...typography.h2, marginTop: 6 }, scopeCard: { paddingHorizontal: 16 }, scopeRow: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingVertical: 15 }, scopeMeta: { flex: 1, gap: 3 }, scopeTitle: { fontSize: 16, fontWeight: '700' }, scopeDetail: { fontSize: 13, lineHeight: 18 }, secondary: { textAlign: 'center', fontSize: 16, fontWeight: '700', paddingVertical: 8 } });
