import React, { useCallback, useState } from 'react';
import { ActivityIndicator, Alert, Linking, Pressable, StyleSheet, Text, View } from 'react-native';
import { useFocusEffect } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import Ionicons from '@expo/vector-icons/Ionicons';
import { Screen } from '../../components/Screen';
import { Card } from '../../components/Card';
import { AppBackButton } from '../../components/AppBackButton';
import { getThemeColors, typography } from '../../design/tokens';
import { RootStackParamList } from '../../navigation/types';
import { useAppContext } from '../../state/AppContext';
import { disconnectExternalConsultant, ExternalAppointment, ExternalConsultantConnection, ExternalDietPlan, getExternalAppointments, getExternalConsultant, getExternalDietPlans, selectExternalDietPlan } from '../../services/externalConsultantService';

type Props = NativeStackScreenProps<RootStackParamList, 'ConsultantConnectionDetails'>;
const dateTime = (value: string) => new Date(value).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });

export const ConsultantConnectionDetailsScreen = ({ navigation, route }: Props) => {
  const { authSession, themeMode } = useAppContext(); const palette = getThemeColors(themeMode); const sessionToken = authSession?.sessionToken ?? '';
  const [connection, setConnection] = useState<ExternalConsultantConnection | null>(null); const [plans, setPlans] = useState<ExternalDietPlan[]>([]); const [appointments, setAppointments] = useState<ExternalAppointment[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const load = useCallback(async () => { setLoading(true); setError(null); try { const detail = await getExternalConsultant(route.params.connectionId, sessionToken); setConnection(detail.connection); const scopes = detail.connection.consented_scopes; const [planResult, appointmentResult] = await Promise.all([scopes.includes('DIET_PLANS') ? getExternalDietPlans(detail.connection.id, sessionToken) : Promise.resolve({ plans: [] }), scopes.includes('APPOINTMENTS') ? getExternalAppointments(detail.connection.id, sessionToken) : Promise.resolve({ appointments: [] })]); setPlans(planResult.plans); setAppointments(appointmentResult.appointments); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Connection details could not be loaded.'); } finally { setLoading(false); } }, [route.params.connectionId, sessionToken]);
  useFocusEffect(useCallback(() => { void load(); }, [load]));
  const disconnect = () => Alert.alert('Disconnect consultant?', 'Their access ends immediately. Existing records remain governed by applicable retention requirements.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Disconnect', style: 'destructive', onPress: async () => { try { await disconnectExternalConsultant(route.params.connectionId, sessionToken); navigation.goBack(); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Disconnect failed.'); } } }]);
  const selectPlan = (plan: ExternalDietPlan) => Alert.alert('Use this diet plan?', 'This changes the plan used for daily adherence. Your other published plans remain available.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Use plan', onPress: async () => { try { await selectExternalDietPlan(route.params.connectionId, plan.id, sessionToken); await load(); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Diet plan selection failed.'); } } }]);
  const name = connection?.consultant?.display_name || 'Connected consultant';

  return <Screen scroll contentStyle={styles.content}><View style={styles.header}><AppBackButton onPress={() => navigation.goBack()} /><Text style={[styles.title, { color: palette.textPrimary }]}>Consultant</Text><View style={styles.placeholder} /></View>
    {loading ? <ActivityIndicator color={palette.blue} style={styles.loader} /> : null}{error ? <Card style={styles.card}><Text accessibilityRole="alert" style={styles.error}>{error}</Text><Pressable onPress={() => void load()}><Text style={[styles.link, { color: palette.blue }]}>Try again</Text></Pressable></Card> : null}
    {connection ? <><View style={styles.identity}><View style={[styles.avatar, { backgroundColor: palette.cardMuted }]}><Text style={[styles.avatarText, { color: palette.blue }]}>{name.slice(0, 1).toUpperCase()}</Text></View><Text style={[styles.hero, { color: palette.textPrimary }]}>{name}</Text><Text style={[styles.body, { color: palette.textSecondary }]}>{connection.consultant?.headline || connection.consultant?.specialisations?.join(' · ') || 'Care professional'}</Text><Text style={styles.connected}>● {connection.state === 'ACTIVE' ? 'Connected' : connection.state}</Text></View>
      {connection.consultant?.phone_e164 ? <Pressable accessibilityRole="button" style={[styles.action, { backgroundColor: '#25D366' }]} onPress={() => void Linking.openURL(`https://wa.me/${connection.consultant?.phone_e164?.replace(/\D/g, '')}`)}><Ionicons name="logo-whatsapp" size={20} color="#FFFFFF" /><Text style={styles.actionText}>Message on WhatsApp</Text></Pressable> : null}
      <Text style={[styles.section, { color: palette.textPrimary }]}>Shared access</Text><Card style={styles.card}>{connection.consented_scopes.map((scope, index) => <View key={scope} style={[styles.row, index > 0 && { borderTopColor: palette.stroke, borderTopWidth: StyleSheet.hairlineWidth }]}><Ionicons name="checkmark-circle" size={20} color="#59D12B" /><Text style={[styles.rowText, { color: palette.textPrimary }]}>{scope.replace(/_/g, ' ').toLowerCase().replace(/^./, (letter) => letter.toUpperCase())}</Text></View>)}</Card>
      <Text style={[styles.section, { color: palette.textPrimary }]}>Diet plans</Text>{plans.length ? plans.map((plan) => <Card key={plan.id} style={styles.card}><View style={styles.planHeader}><Text style={[styles.cardTitle, { color: palette.textPrimary }]}>{plan.title}</Text>{plan.is_active ? <Text style={styles.activeBadge}>ACTIVE</Text> : null}</View><Text style={[styles.body, { color: palette.textSecondary }]}>Version {plan.plan_version} · Published {new Date(plan.published_at).toLocaleDateString()}</Text>{!plan.is_active ? <Pressable accessibilityRole="button" style={[styles.planButton, { borderColor: palette.blue }]} onPress={() => selectPlan(plan)}><Text style={[styles.link, { color: palette.blue }]}>Use for daily tracking</Text></Pressable> : null}</Card>) : <Card style={styles.card}><Text style={[styles.body, { color: palette.textSecondary }]}>No diet plans have been published by this consultant.</Text></Card>}
      <Text style={[styles.section, { color: palette.textPrimary }]}>Appointments</Text>{appointments.length ? appointments.map((appointment) => <Card key={appointment.id} style={styles.card}><Text style={[styles.cardTitle, { color: palette.textPrimary }]}>{appointment.title}</Text><Text style={[styles.body, { color: palette.textSecondary }]}>{dateTime(appointment.starts_at)}</Text><Text style={[styles.status, { color: palette.blue }]}>{appointment.status}</Text></Card>) : <Card style={styles.card}><Text style={[styles.body, { color: palette.textSecondary }]}>No appointments are scheduled through this connection.</Text></Card>}
      <Pressable accessibilityRole="button" style={[styles.disconnect, { borderColor: '#FF5A5F' }]} onPress={disconnect}><Text style={styles.disconnectText}>Disconnect Consultant</Text></Pressable>
    </> : null}
  </Screen>;
};

const styles = StyleSheet.create({ content: { paddingHorizontal: 20, paddingTop: 14, paddingBottom: 48, gap: 15 }, header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }, circle: { width: 44, height: 44, borderWidth: 1, borderRadius: 22, alignItems: 'center', justifyContent: 'center' }, placeholder: { width: 44 }, title: { ...typography.h3 }, loader: { marginTop: 60 }, identity: { alignItems: 'center', gap: 7, paddingVertical: 20 }, avatar: { width: 76, height: 76, borderRadius: 25, alignItems: 'center', justifyContent: 'center' }, avatarText: { fontSize: 30, fontWeight: '700' }, hero: { ...typography.h1 }, body: { ...typography.body, lineHeight: 21 }, connected: { color: '#59D12B', fontSize: 14, fontWeight: '700' }, section: { ...typography.h2, marginTop: 8 }, card: { padding: 17, gap: 8 }, cardTitle: { ...typography.h3 }, planHeader: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: 8 }, activeBadge: { color: '#59D12B', fontSize: 11, fontWeight: '800', letterSpacing: 0.8 }, planButton: { minHeight: 44, borderWidth: 1, borderRadius: 14, alignItems: 'center', justifyContent: 'center', marginTop: 6 }, row: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 11 }, rowText: { fontSize: 16, fontWeight: '600' }, status: { fontSize: 13, fontWeight: '700' }, action: { minHeight: 52, borderRadius: 17, alignItems: 'center', justifyContent: 'center', flexDirection: 'row', gap: 9 }, actionText: { color: '#FFFFFF', fontSize: 16, fontWeight: '700' }, disconnect: { minHeight: 52, borderWidth: 1, borderRadius: 17, alignItems: 'center', justifyContent: 'center', marginTop: 8 }, disconnectText: { color: '#FF5A5F', fontSize: 16, fontWeight: '700' }, error: { color: '#FF6B6B', fontSize: 14 }, link: { fontSize: 15, fontWeight: '700' } });
